 function setObjective(title,detail){$('#objective b').textContent=title;$('#objective small').innerHTML=detail}
 function changeMood(n){state.mood=THREE.MathUtils.clamp(state.mood+n,0,100);if(state.mood<=0&&!state.cry){state.cry=true;$('#cryOverlay').classList.add('visible');setTimeout(()=>{state.mood=55;state.cry=false;$('#cryOverlay').classList.remove('visible');toast('Bir nefes aldın. Hazırsan devriyeye dön!')},3300)}}
 function updateHUD(){let m=Math.round(state.mood);$('#moodValue').textContent=m+'%';$('#moodBar').style.width=m+'%';$('#shoeValue').textContent=state.shoe<8?'KULLANILAMAZ':state.shoe<40?'YIPRANMIŞ':state.shoe<70?'ISLAK':'SAĞLAM';$('#shoeBar').style.width=state.shoe+'%';$('#shoeBar').style.background=state.shoe<35?'#d97e7e':state.shoe<70?'#e1ba7d':'#80c4b8';$('#shoeTag').textContent='✦ '+state.shoeName;$('#outfitTag').textContent=state.wardrobe.shirt||'Beyaz gömlek';$('#missionBar').style.width=Math.min(100,state.missionProgress/3*100)+'%';$('#missionText').textContent=state.mission===0?`Sahil yolunu kontrol et · ${Math.min(3,state.missionProgress)} / 3`:`${state.eventsHandled} olaya müdahale edildi`;$('#ownedCount').textContent=`Koleksiyonun: ${state.owned.size} parça`}
 function targetEvent(){return eventSpots[state.activeEvent%eventSpots.length]}
-function activateEvent(){let e=targetEvent();let obj=e.npc;if(e.type==='Lost child'){obj=civilians[3]}else if(e.type==='Beach call'){obj=civilians[7]}else if(e.type==='Lost wallet'){obj=civilians[10]}else{obj=e.npc}
+function activateEvent(){if(!state.started||state.activeIncident)return;let e=targetEvent();let obj=e.npc;if(e.type==='Lost child'){obj=civilians[3]}else if(e.type==='Beach call'){obj=civilians[7]}else if(e.type==='Lost wallet'){obj=civilians[10]}else{obj=e.npc}
  obj.group.visible=true;state.activeTarget=obj;state.activeIncident=e;let mark=sphere(scene,e.x,2.4,e.z,.18,.18,.18,M.yellow);mark.userData.eventMark=true;if(state.eventMark)scene.remove(state.eventMark);state.eventMark=mark;toast('YARDIM ÇAĞRISI · '+e.label);setObjective(e.label,`${e.detail} · <kbd>E</kbd>`);changeMood(-5);}
 function resolveEvent(){let e=state.activeIncident;if(!e){toast('Yakında bekleyen bir olay yok.');return}if(e.type==='Lost child'||e.type==='Beach call'||e.type==='Lost wallet'){toast(e.type==='Lost child'?'Aile yeniden bir arada. Küçük bir iyilik, büyük bir rahatlama.':e.type==='Beach call'?'Sivil güvende. Sahil ekibine haber verdin.':'Cüzdan sahibine ulaştı. Güzel iş!');state.activeTarget.group.position.x+=2;changeMood(13)}else{toast('Şüpheli durduruldu. Destek ekibi olayı devraldı.');state.activeTarget.group.position.x+=2.5;changeMood(15)}
  if(state.eventMark){scene.remove(state.eventMark);state.eventMark=null}state.activeIncident=null;state.eventsHandled++;state.missionProgress++;$('#missionTitle').textContent=state.missionProgress>=3?'Devriye tamamlandı · Yeni çağrı':'Sahil devriyesi';if(state.missionProgress>=3){state.mission=1;state.missionProgress=0;setTimeout(()=>{toast('GÖREV TAMAMLANDI · Yeni vardiya hedefi açıldı!');$('#missionTitle').textContent='Şehrin yanında ol';setObjective('Şehrin yanında ol','Yeni bir çağrı için devriyeye devam et')},650)}else setObjective('Devriye sürüyor','Yakındaki bir olay için <kbd>E</kbd> tuşuna bas');state.activeEvent++;updateHUD();setTimeout(activateEvent,10500)}
 function wearItem(item){state.wardrobe={...item};state.owned.add(item.name);if(item.kind==='heel'||item.kind==='flat'){state.shoeName=item.name;state.shoeType=item.kind;state.heel=item.heel||0;state.shoe=100;state.wet=false;for(let s of [-1,1]){avatar.children.filter(c=>c.position.y<.2&&c.position.x*s>0).slice(-1)[0]?.material?.color?.set(item.color)}toast(item.kind==='flat'?`${item.name} giyildi. Ayakların rahatlayacak.`:`${item.name} hazır. Şıklık tamam, dikkatli adımlar!`);$('#fitName').textContent=item.name}else if(item.kind==='shirt'){state.wardrobe.shirt=item.name;toast(`${item.name} seçildi. Üniformana çok yakıştı.`)}else if(item.kind==='tights'){state.wardrobe.tights=item.name;toast(`${item.name} giyildi. Görünüm güncellendi.`)}updateHUD()}

